import sys
import json

def main():
    data = sys.stdin.read()
    if not data.strip():
        return
    arr = json.loads(data)
    print(sum(arr))

if __name__ == "__main__":
    main()

import sys
import json

def main():
    try:
        data = json.load(sys.stdin)
        if isinstance(data, list):
            total = sum(data)
            print(total)
    except Exception:
        pass

if __name__ == "__main__":
    main()

